import { todayISO } from './deadline';

/** Keep date-derived tracker state current across midnight and suspended tabs. */
export function startDayRefresh(refresh: () => void): () => void {
  let day = todayISO();
  let timer: number | undefined;
  let active = true;

  function schedule() {
    window.clearTimeout(timer);
    if (!active) return;
    const now = new Date();
    const midnight = new Date(now);
    // Calendar arithmetic keeps this correct on 23-hour and 25-hour DST days.
    midnight.setHours(24, 0, 0, 0);
    timer = window.setTimeout(check, Math.max(1, midnight.getTime() - now.getTime()));
  }

  function check() {
    if (!active) return;
    try {
      const current = todayISO();
      if (current !== day) {
        day = current;
        refresh();
      }
    } finally {
      schedule();
    }
  }

  function visible() {
    if (document.visibilityState === 'visible') check();
  }

  window.addEventListener('focus', check);
  window.addEventListener('pageshow', check);
  document.addEventListener('visibilitychange', visible);
  schedule();

  return () => {
    active = false;
    window.clearTimeout(timer);
    window.removeEventListener('focus', check);
    window.removeEventListener('pageshow', check);
    document.removeEventListener('visibilitychange', visible);
  };
}

export type Status = 'ok' | 'soon' | 'urgent' | 'expired';

const toDate = (s: string) => {
  const [y, m, d] = s.split('-').map(Number);
  return new Date(y, m - 1, d);
};
const fmt = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

export function dueDate(orderDate: string, days: number): string {
  const d = toDate(orderDate);
  d.setDate(d.getDate() + days);
  return fmt(d);
}

export function daysLeft(due: string, today: string): number {
  const ms = toDate(due).getTime() - toDate(today).getTime();
  return Math.round(ms / 86_400_000);
}

export function status(left: number): Status {
  if (left < 0) return 'expired';
  if (left <= 2) return 'urgent';
  if (left <= 7) return 'soon';
  return 'ok';
}

export const todayISO = () => fmt(new Date());

// RFC 5545 §3.3.11: newlines belong inside TEXT as an escaped value, never
// as content-line delimiters. Replace unsupported controls visibly in the
// exported reminder; the saved order itself is unchanged.
const esc = (s: string) => s.replace(/\\/g, '\\\\')
  .replace(/\r\n|\r|\n/g, '\\n')
  .replace(/[,;]/g, (c) => '\\' + c)
  .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '\ufffd');

const encoder = new TextEncoder();

// RFC 5545 §3.1 counts UTF-8 octets, including the continuation space.
// Iterate code points so a fold cannot divide a multibyte character.
function fold(line: string): string {
  let output = '', bytes = 0;
  for (const character of line) {
    const size = encoder.encode(character).byteLength;
    if (bytes + size > 75) {
      output += '\r\n ';
      bytes = 1;
    }
    output += character;
    bytes += size;
  }
  return output;
}

export function buildIcs(o: { id: string; merchant: string; orderNo?: string; due: string }, stamp = new Date()): string {
  const d = o.due.replace(/-/g, '');
  const end = new Date(+o.due.slice(0, 4), +o.due.slice(5, 7) - 1, +o.due.slice(8, 10) + 1);
  const e = `${end.getFullYear()}${String(end.getMonth() + 1).padStart(2, '0')}${String(end.getDate()).padStart(2, '0')}`;
  const ts = stamp.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
  const title = esc(`Return deadline: ${o.merchant || 'order'}${o.orderNo ? ' #' + o.orderNo : ''}`);
  return [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//ReturnBy//EN', 'CALSCALE:GREGORIAN',
    'BEGIN:VEVENT', `UID:${esc(o.id)}@returnby`, `DTSTAMP:${ts}`,
    `DTSTART;VALUE=DATE:${d}`, `DTEND;VALUE=DATE:${e}`, `SUMMARY:${title}`,
    'BEGIN:VALARM', 'ACTION:DISPLAY', `DESCRIPTION:${title}`, 'TRIGGER:-P3D', 'END:VALARM',
    'END:VEVENT', 'END:VCALENDAR', '',
  ].map(fold).join('\r\n');
}

